class Solution:
    def isPossibleToRearrange(self, s: str, t: str, k: int) -> bool:
        m = len(s) // k
        a = [s[i*m:(i+1)*m] for i in range(k)]
        b = [t[i*m:(i+1)*m] for i in range(k)]
        used = [False] * k
        for x in a:
            found = False
            for j in range(k):
                if not used[j] and b[j] == x:
                    used[j] = True
                    found = True
                    break
            if not found:
                return False
        return True

