class Solution {
public:
    bool isPossibleToRearrange(string s, string t, int k) {
        int m = s.size() / k;
        vector<string> a, b;
        for (int i = 0; i < k; i++) {
            a.push_back(s.substr(i * m, m));
            b.push_back(t.substr(i * m, m));
        }
        vector<bool> used(k, false);
        for (auto &x : a) {
            bool found = false;
            for (int j = 0; j < k; j++) {
                if (!used[j] && b[j] == x) { used[j] = true; found = true; break; }
            }
            if (!found) return false;
        }
        return true;
    }
};

