import java.util.*;

class Solution {
    public boolean isPossibleToRearrange(String s, String t, int k) {
        int m = s.length() / k;
        Map<String, Integer> cnt = new HashMap<>();
        for (int i = 0; i < k; i++)
            cnt.merge(s.substring(i * m, (i + 1) * m), 1, Integer::sum);
        for (int i = 0; i < k; i++) {
            String c = t.substring(i * m, (i + 1) * m);
            int v = cnt.getOrDefault(c, 0);
            if (v == 0) return false;
            cnt.put(c, v - 1);
        }
        return true;
    }
}

