import java.util.*;

class Solution {
    public boolean isPossibleToRearrange(String s, String t, int k) {
        int m = s.length() / k;
        List<String> a = new ArrayList<>(), b = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            a.add(s.substring(i * m, (i + 1) * m));
            b.add(t.substring(i * m, (i + 1) * m));
        }
        Collections.sort(a);
        Collections.sort(b);
        return a.equals(b);
    }
}

